import re
import logging
import time
from taf.rfrl.cbts.utilities import generic_utils
from taf.rfrl.cbts.utilities import tl_config
from taf.rfrl.cbts.utilities import time_convert
from taf.rfrl.cbts.connections.ssh_connections import SSHConnExec
from robot.api import logger


class KoreDump(SSHConnExec):

    def check_cordump_on_vcu(self, dir, start_time=0, gnb_index=0):
        """
        Checking coredump on vcu, if has, collect the coredump logs

        :param str dir: the dir of local machine to download the coredump logs.
        :param int starttime: start utc time of available coredumps, get from get_current_utc_timestamp, default is 0.
        :param int: the index of gnb, default is 0.
        """
        alias = generic_utils.get_unique_id_string()
        namespace = tl_config.get_vcu_namespace(gnb_index=gnb_index)
        SSHConnExec.connect_to_vcu_cloud_hosting(self, using_tenant=False, alias=alias, gnb_index=gnb_index)
        is_installed = self.is_koredump_installed(alias=alias)
        if is_installed is True:
            self.collect_koredump_log(dir=dir, start_time=start_time, namespace=namespace, alias=alias)
        else:
            logging.info('Koredump tool is not installed.')

    def check_cordump_on_vdu(self, dir, start_time=0, gnb_index=0, vdu_index=0, conn_prompt=None):
        """
        Checking coredump on vdu, if has, collect the coredump logs

        :param str dir: the dir of local machine to download the coredump logs.
        :param int starttime: start utc time of available coredumps, get from get_current_utc_timestamp, default is 0.
        :param int: the index of gnb, default is 0.
        :param int: the index of vdu, default is 0.
        :param str: user define connection prompt, default is None.
        """
        alias = generic_utils.get_unique_id_string()
        namespace = tl_config.get_vdu_namespace(gnb_index=gnb_index, vdu_index=vdu_index)
        SSHConnExec.connect_to_vdu_cloud_hosting(self, using_tenant=False,
                                                 prompt=conn_prompt, alias=alias, gnb_index=gnb_index,
                                                 vdu_index=vdu_index)
        is_installed = self.is_koredump_installed(alias=alias)
        logger.console(is_installed)
        if is_installed is True:
            self.collect_koredump_log(dir=dir, start_time=start_time, namespace=namespace, alias=alias)
        else:
            logging.info('Koredump tool is not installed.')

    def is_koredump_installed(self, alias='default'):
        is_koredump_installed = False
        base_cmd = 'koredumpctl status'
        cmd_1 = '|grep Running | wc -l'
        cmd_2 = '|grep koredump-ds | wc -l'
        running_pod_num = SSHConnExec.execute_normal_cmd(self, base_command=base_cmd, pipe_cmd=cmd_1, alias=alias)
        koredump_pod_num = SSHConnExec.execute_normal_cmd(self, base_command=base_cmd, pipe_cmd=cmd_2, alias=alias)
        try:
            if int(running_pod_num) == int(koredump_pod_num) + 1:
                is_koredump_installed = True
        except Exception as e:
            logger.warn("koredump tool is not working well", e)
        finally:
            return is_koredump_installed

    def collect_koredump_log(self, dir, namespace, start_time, alias='default'):
        cmd = 'koredumpctl list -n {namespace} | wc -l'.format(namespace=namespace)
        output = SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        if 'Nothing found' not in output:
            self._collect_coredump_log_via_koredump(dir=dir, start_time=start_time, namespace=namespace, alias=alias)
        else:
            logging.info('end coredump check')

    def _collect_coredump_log_via_koredump(self, dir, start_time, namespace, alias='default'):
        tmp_dir = 'tmp_corelog_' + namespace
        cmd = 'rm -rf {tmp_dir}'.format(tmp_dir=tmp_dir)
        SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        cmd = 'mkdir {tmp_dir} && cd {tmp_dir}'.format(tmp_dir=tmp_dir)
        SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        cmd = 'nohup koredumpctl list -n {namespace} &'.format(namespace=namespace)
        output = SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        get_koredump_done = False
        for i in range(3):
            time.sleep(10)
            get_koredump_done = self._check_get_koredump_list_is_done(namespace=namespace, alias=alias)
            print(get_koredump_done)
            if get_koredump_done is True:
                break
        cmd = 'cat nohup.out'
        output = SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        core_dump_list = self._get_core_dump_info(start_time=start_time, info=output)
        logger.info(core_dump_list)
        if core_dump_list:
            self._collect_coredump(dir=dir, core_dump_list=core_dump_list, alias=alias)

    def _check_get_koredump_list_is_done(self, namespace, alias='default'):
        check_cmd = 'koredumpctl list -n {namespace}'.format(namespace=namespace)
        cmd = 'ps -ef | grep +\'' + check_cmd + '\''
        output = SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        if 'nohup' in output and namespace in output:
            return False
        else:
            return True

    def _get_core_dump_info(self, info, start_time):
        available_coredump_info_list = []
        coredump_info_list = info.split("\n- ")
        for coredump_info in coredump_info_list:
            id = re.findall('ID\\:\\s*\\S+\\.lz4', coredump_info)
            if id:
                id = id[0].strip('ID:').lstrip()
            node = re.findall('Node\\:\\s*\\S+', coredump_info)
            if node:
                node = node[0].strip('Node:').lstrip()
            timestamp = re.findall('Timestamp\\:\\s*\\S+', coredump_info)
            if timestamp:
                timestamp = timestamp[0].strip('Timestamp:').lstrip()
                time_stamp = time_convert.time_str_to_utc_timestamp(time_str=timestamp, time_format="%Y-%m-%dT%H:%M:%SZ")
            if time_stamp >= start_time:
                temp_dict = {'ID': id, 'Node': node, 'details': coredump_info}
                available_coredump_info_list.append(temp_dict)
        return available_coredump_info_list

    def _collect_coredump(self, core_dump_list, dir, alias='default'):
        for core_dump in core_dump_list:
            logger.console(core_dump["details"])
            self._collect_single_coredump(node=core_dump['Node'], coredump_id=core_dump['ID'], alias=alias)
        cmd = 'nohup tar -cvf coredumplog.gz *.lz4 &'
        SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        tar_log_done = False
        for i in range(5):
            time.sleep(2)
            tar_log_done = self._check_tar_log_done(alias=alias)
            print(tar_log_done)
            if tar_log_done is True:
                break
        remote_path = SSHConnExec.execute_normal_cmd(self, base_command='pwd', alias=alias)
        time_stamp = SSHConnExec.execute_normal_cmd(self, base_command='date +"%Y-%m-%d %H:%M:%S"', alias=alias)
        local_file_path = dir + '/coredump_' + time_stamp
        remote_path = remote_path + '/coredumplog.gz'
        local_file_path = local_file_path + '/coredumplog.gz'
        SSHConnExec.download_file(self, remote_path=remote_path, local_path=local_file_path, alias=alias)

    def _collect_single_coredump(self, node, coredump_id, alias='default'):
        cmd = 'koredumpctl get {node} {coredump_id}'.format(node=node,
                                                            coredump_id=coredump_id)
        SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)

    def _check_tar_log_done(self, alias='default'):
        check_cmd = 'tar -cvf'
        cmd = 'ps -ef | grep +\'' + check_cmd + '\''
        output = SSHConnExec.execute_normal_cmd(self, base_command=cmd, alias=alias)
        print(output)
        if 'nohup' in output:
            return False
        else:
            return True
